class Solution:

	def matrixMultiplication(self, N, arr):
		maxint = 10 ** 9 + 7
		table = [[0 for _ in range(N)] for _ in range(N)]
		for i in range(N):
			table[i][i] = 0
		for L in range(2, N):
			for i in range(1, N - L + 1):
				j = i + L - 1
				table[i][j] = maxint
				for k in range(i, j):
					Q = table[i][k] + table[k + 1][j] + arr[i - 1] * arr[k] * arr[j]
					table[i][j] = min(Q, table[i][j])
		return table[1][N - 1]
